contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint f, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (f) + (amount)); require(f <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= f + amount);
        // Fund C with f (owner-only Command with empty calldata hits receive())
        c.Command{value: f}(address(c), ""); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        // Self-multiplication: value either stays (no-op branch) or is transferred back to c
        c.multiplicate{value: amount}(address(c)); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore + amount);
    }
    receive() external payable {}
}

