// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(uint256 f, uint256 amount) internal {
        f = bound(f, 0, 1000000000000000000000000000000);
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= f + amount);
        try c.Command{value: f}(address(c), "") {} catch { return; }
        uint balBefore = address(c).balance;
        try c.multiplicate{value: amount}(address(c)) {} catch { return; }
        assertTrue(address(c).balance == balBefore + amount);
    }

    function testFuzz_run(uint256 f, uint256 amount) public {
        _run(f, amount);
    }

    receive() external payable {}
}
